Translate("ptBR", "moonglade", {
	title = "Clareira da Lua",
	aliases = { "a clareira" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Clareira da Lua é um vale oculto nas montanhas do norte de {link:kalimdor}Kalimdor{/link}, entre a {link:felwood}Selva Maleva{/link} e {link:winterspring}Hibérnia{/link}. Um lago tranquilo fica em seu coração, cercado de relva prateada e árvores antigas, e em suas margens está a aldeia de {link:nighthaven}Refúgio Noturno{/link}. Este é o solo sagrado do {link:cenarion-circle}Círculo Cenariano{/link}, a ordem dos druidas, e a sede do {link:keeper-remulos}Guardião Remulos{/link}, filho de {link:cenarius}Cenarius{/link}. Nenhum exército a domina. Elfos noturnos e taurens andam por seus caminhos como amigos, e seus guardiões não toleram violência dentro de suas fronteiras.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra o ano em que os druidas fizeram da Clareira da Lua o seu refúgio pela primeira vez. Seus nomes contam algo de seu passado. O lago leva o nome de Eluna, a deusa da lua dos {link:night-elves}elfos noturnos{/link}. Os túmulos do leste levam o nome de {link:malfurion-stormrage}Malfurion Stormrage{/link}, o primeiro druida, cujos seguidores aprenderam a dormir por longas eras no {link:emerald-dream}Sonho Esmeralda{/link}. Os druidas dizem que os que hibernam na Clareira da Lua dormem sob a vigilância do guardião. Nunca foi uma cidade nem uma fortaleza, apenas um lugar de ensino e de repouso.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[A clareira está em paz, mas o Círculo que nela habita não está. {link:malfurion-stormrage}Malfurion{/link} dorme e não voltou. Em {link:darnassus}Darnassus{/link}, o Arquidruida {link:fandral-staghelm}Fandral Staghelm{/link} lidera os druidas dos elfos noturnos, e ele e o {link:keeper-remulos}Guardião Remulos{/link} passaram a desconfiar um do outro. Cada um suspeita que o outro trama algo, enquanto a estranha corrupção de {link:teldrassil}Teldrassil{/link} continua sem cura. A Clareira da Lua voltou-se, então, para fora. Seus druidas acolheram os {link:tauren}taurens{/link} e, por meio deles, a {link:horde}Horda{/link}. Seus enviados buscam ajuda de qualquer povo disposto a dá-la: contra o veneno na {link:darkshore}Costa Negra{/link}, contra a Felvine de Eldre'Thalas e contra um mal antigo que se agita em {link:silithus}Silithus{/link}. Recentemente, druidas {link:skyborne}shen'dorei{/link}, vindos de uma ilha distante no céu, chegaram a {link:nighthaven}Refúgio Noturno{/link}, e um espírito de sua terra natal veio encontrá-los.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os druidas do {link:cenarion-circle}Círculo Cenariano{/link}.{/b} Elfos noturnos e taurens que ensinam, estudam e dormem na clareira, liderados pelo {link:keeper-remulos}Guardião Remulos{/link} e por seu mordomo, {link:rabine-saturna}Rabine Saturna{/link}.
• {b}Os guardiões da Clareira da Lua.{/b} {link:sentinels}Sentinelas{/link} do Círculo que mantêm a paz da clareira e guardam seu santuário.
• {b}Os grandes espíritos.{/b} Espíritos antigos da natureza selvagem, que ensinam aos jovens druidas as formas de sua espécie.
• {b}Os mortos inquietos.{/b} Nos {link:stormrage-barrow-dens}Templos de Tempesfúria{/link}, os espíritos de Druidas da Garra caídos vagam cheios de fúria.
• {b}Os {link:timbermaw-furbolgs}Presamatos{/link}.{/b} Os pelursos do {link:timbermaw-hold}Domínio dos Presamatos{/link} guardam os túneis que são a única estrada para a clareira, e não recebem bem todo viajante.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Era dos Antigos.{/b} Os druidas aprenderam seu ofício com {link:cenarius}Cenarius{/link} na {link:war-of-the-ancients}Guerra dos Antigos{/link} e o mantiveram ao longo de dez mil anos, a maior parte deles passada em sono.
• {b}A {link:third-war}Terceira Guerra{/link}.{/b} Quando a {link:burning-legion}Legião Ardente{/link} voltou, os druidas despertaram para lutar. Cenarius caiu no {link:ashenvale}Vale Gris{/link}, e na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link} {link:nordrassil}Nordrassil{/link} entregou seu poder para destruir {link:archimonde}Archimonde{/link}.
• {b}O Círculo Aberto.{/b} Depois da guerra, o Círculo acolheu druidas taurens, o primeiro deles {link:hamuul-runetotem}Hamuul Runetotem{/link}. A Clareira da Lua tornou-se terra comum dos dois povos.]=],
		},
		{
			title = "Saberes da Clareira",
			text = [=[• Os druidas falam de Omen, um grande lobo da {link:war-of-the-ancients}Guerra dos Antigos{/link} que a magia demoníaca voltou contra seus aliados. Derrubado na Clareira da Lua, ele dorme no {link:lake-elune-ara}Lago Eluna'ara{/link} e se agita uma vez por ano, no Festival Lunar.
• Ao sul da clareira, além da {link:felwood}Selva Maleva{/link} e de {link:winterspring}Hibérnia{/link}, erguem-se as alturas do {link:mount-hyjal}Monte Hyjal{/link}, onde {link:nordrassil}Nordrassil{/link} ainda se ergue. Os túmulos dos Druidas da Garra também correm fundo sob essa montanha, e os mais profundos deles se chamam {link:the-barrow-deeps}The Barrow Deeps{/link}.
• {link:umber}Umber{/link}, o arquivista de {link:nighthaven}Refúgio Noturno{/link}, avisa a cada visitante que nunca deixe {link:rabine-saturna}Rabine Saturna{/link} esperando. Quem deixa, diz ele, pode acabar coberto de mel.]=],
		},
	},
})

Translate("ptBR", "nighthaven", {
	title = "Refúgio Noturno",
	sections = {
		{
			title = "Resumo",
			text = [=[Refúgio Noturno é a única aldeia da {link:moonglade}Clareira da Lua{/link}, construída ao longo das margens do {link:lake-elune-ara}Lago Eluna'ara{/link}. Suas casas são erguidas no estilo antigo dos elfos noturnos, e ao lado delas ficam as tendas dos druidas taurens que se uniram ao Círculo. {link:rabine-saturna}Rabine Saturna{/link} cuida dos assuntos da aldeia pelo {link:keeper-remulos}Guardião Remulos{/link}. {link:dendrite-starblaze}Dendrite Starblaze{/link} e {link:loganaar}Loganaar{/link} ensinam os jovens druidas que vêm para cá, e o arquivista {link:umber}Umber{/link} vagueia entre suas estantes. Montadores do Círculo levam druidas a {link:darnassus}Darnassus{/link} e ao {link:thunder-bluff}Penhasco do Trovão{/link}, enquanto hipogrifos e serpes esperam nas bordas da clareira. Refúgio Noturno é remoto e reservado. Só no Festival Lunar abre os braços a todos os povos do mundo.]=],
		},
	},
})

Translate("ptBR", "shrine-of-remulos", {
	title = "Santuário de Remulos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Santuário de Remulos fica no noroeste da {link:moonglade}Clareira da Lua{/link}, entre árvores antigas à beira do lago. Aqui o próprio guardião costuma manter sua vigília. O santuário é um tributo ao trabalho do {link:cenarion-circle}Círculo Cenariano{/link}, a preservação da natureza e do equilíbrio, e a guardiã {link:tajarri}Tajarri{/link} o serve. Os jovens druidas que passam na Prova do Lago trazem uma bugiganga das águas e a oferecem no santuário como sinal de respeito. Não muito ao norte, o {link:great-bear-spirit}Grande Espírito do Urso{/link} tem sua morada.]=],
		},
	},
})

Translate("ptBR", "lake-elune-ara", {
	title = "Lago Eluna'ara",
	aliases = { "Eluna'ara" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Lago Eluna'ara enche o coração da {link:moonglade}Clareira da Lua{/link}. Leva o nome de Eluna, e suas águas claras e profundas refletem a lua sobre a clareira. {link:nighthaven}Refúgio Noturno{/link} fica em suas margens, e pontes o atravessam onde a terra se estreita. O lago faz parte do ensino do Círculo. Jovens druidas mergulham em suas profundezas em busca de bugigangas do santuário, que se desfazem depressa quando trazidas ao ar. O lago guarda também um segredo mais antigo. Dizem que o lobo caído Omen dorme em seu lodo, abençoado por Eluna e incapaz de morrer.]=],
		},
	},
})

Translate("ptBR", "stormrage-barrow-dens", {
	title = "Templos de Tempesfúria",
	aliases = { "Templo de Tempesfúria" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Templos de Tempesfúria ficam no sudeste da {link:moonglade}Clareira da Lua{/link}, atrás de um grande portão na encosta. Levam o nome de {link:malfurion-stormrage}Malfurion Stormrage{/link} e são o lugar de repouso dos druidas. Nem todos os que ali jazem descansam em paz. Espíritos enfurecidos de Druidas da Garra vagam pelos salões e atacam quem quer que entre. O {link:great-cat-spirit}Grande Espírito do Gato{/link}, que vive ali perto, guarda três relíquias de seu favor nos templos. Uma estátua na entrada empresta um manto de sombra aos que precisam passar despercebidos pelos espíritos para recuperá-las.]=],
		},
	},
})

Translate("ptBR", "keeper-remulos", {
	title = "Guardião Remulos",
	subtitle = "Guardião da Clareira da Lua",
	found = "O Santuário de Remulos, a noroeste de Refúgio Noturno",
	hint = "Procure o filho de Cenarius no santuário que leva seu nome.",
	allegiance = "Círculo Cenariano",
	aliases = { "Remulos" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Guardião Remulos é um filho do semideus {link:cenarius}Cenarius{/link} e o guardião da {link:moonglade}Clareira da Lua{/link}. Como o pai, é um ser da natureza selvagem, tanto floresta quanto carne. Vigia a clareira sagrada e os druidas que nela dormem, e guia o {link:cenarion-circle}Círculo Cenariano{/link} em seu trabalho: a preservação da natureza e do equilíbrio.]=],
		},
		{
			title = "Importância",
			text = [=[Com {link:malfurion-stormrage}Malfurion Stormrage{/link} perdido no {link:emerald-dream}Sonho Esmeralda{/link}, os druidas têm dois centros e dois líderes. Em {link:darnassus}Darnassus{/link}, o Arquidruida {link:fandral-staghelm}Fandral Staghelm{/link} governa dos ramos da nova Árvore do Mundo. Na {link:moonglade}Clareira da Lua{/link}, Remulos guarda o solo mais antigo. Os dois já não confiam um no outro. Remulos escolheu abrir a clareira a todos que servem ao mundo vivo, taurens e elfos noturnos, {link:horde}Horda{/link} e {link:alliance}Aliança{/link} igualmente. É de sua clareira, e não da cidade do Arquidruida, que o Círculo agora chama campeões mortais contra os perigos de {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "Um Filho de Cenarius",
			text = [=[Os guardiões do bosque são os filhos de {link:cenarius}Cenarius{/link}, e Remulos é um deles. Seu irmão Zaetar foi o primeiro filho. Há muito tempo, Zaetar procurou a Princesa Theradras, um grande poder da terra elemental, e ela lhe deu os primeiros centauros. Os próprios filhos se voltaram contra ele e o mataram, e Theradras levou seus restos para as cavernas de {red:maraudon}Maraudon{/red}. Remulos acreditou que o irmão estava perdido para sempre na arrogância e na fúria. Então, na {link:third-war}Terceira Guerra{/link}, seu pai caiu diante dos orcs no {link:ashenvale}Vale Gris{/link}. Remulos perdeu muito para as raças mortais. Não fechou {link:moonglade}a clareira{/link} para elas.]=],
		},
		{
			title = "Feitos",
			text = [=[• Guarda a {link:moonglade}Clareira da Lua{/link} e os druidas que ali hibernam.
• Guia o {link:cenarion-circle}Círculo Cenariano{/link} a partir do {link:shrine-of-remulos}Santuário de Remulos{/link}.
• Por meio de seu mordomo, {link:rabine-saturna}Rabine Saturna{/link}, chama os povos do mundo a ajudar o Círculo em {link:silithus}Silithus{/link} e nas ruínas de Eldre'Thalas.
• Acolhe na clareira os taurens e, por meio deles, a {link:horde}Horda{/link}.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Pouco se escreveu sobre Remulos antes da era presente: que papel teve nas guerras do mundo antigo, ou quando veio guardar a {link:moonglade}Clareira da Lua{/link} pela primeira vez. Esta entrada registra apenas o que suas palavras e seu posto revelam.]=],
		},
	},
	chapters = {
		{
			title = "O Círculo Dividido",
			hint = "Atenda ao chamado do Círculo na Clareira da Lua.",
			text = [=[Quando o Círculo pediu ajuda no extremo oeste, o chamado partiu pelo {link:thunder-bluff}Penhasco do Trovão{/link} e por {link:darnassus}Darnassus{/link}. No Penhasco do Trovão, foi ouvido com gosto. Em Darnassus, o Arquidruida recusou-se a ouvi-lo pessoalmente. Avisou que a {link:moonglade}Clareira da Lua{/link} falava apenas propaganda, e que só ele tirara seu povo da escuridão. Seu próprio braço direito admitiu que o Arquidruida e o guardião suspeitavam um do outro de trapaça. Aos que foram à clareira mesmo assim, prometeu-se que estavam entre amigos e que nenhum mal vindo de Darnassus os alcançaria ali.]=],
		},
		{
			title = "A Semente de Zaetar",
			hint = "Traga ao guardião um presente do espírito de seu irmão.",
			text = [=[No fundo de Maraudon, onde Theradras guardava seus restos, o espírito de Zaetar permanecia. Ele não abandonaria seus filhos, mesmo depois de tudo o que haviam feito. Enviou, em vez disso, a primeira semente que brotara da vida que seus restos haviam alimentado, com uma mensagem para o irmão: que seu espírito perdurava ali. Quando a semente chegou à {link:moonglade}Clareira da Lua{/link}, Remulos compreendeu. Seu irmão não estava perdido. Havia se devolvido à natureza, como era seu dever, e enfim encontrara a paz. O guardião sentiu que a semente teria importância um dia para o povo daquela terra devastada pela guerra.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, enviado a seu mordomo]=],
		},
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, enviado de {link:darnassus}Darnassus{/link}]=],
		},
		{ text = "The New Frontier" },
		{ text = "Seed of Life" },
		{ text = "Trial of the Lake, em seu santuário" },
	},
	bonds = {
		{ id = "cenarius", name = "Cenarius", note = "seu pai" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "o primeiro druida, que dorme" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "seu rival em Darnassus" },
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "seu mordomo" },
		{ id = "tajarri", name = "Tajarri", note = "guardiã de seu santuário" },
		{ id = "keeper-marandis", name = "Guardião Marandis", note = "busca os restos de seu irmão" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "traz os taurens ao Círculo" },
	},
})

Translate("ptBR", "rabine-saturna", {
	title = "Rabine Saturna",
	subtitle = "Mordomo do Guardião Remulos",
	found = "Refúgio Noturno, junto ao lago",
	hint = "Procure o mordomo do guardião na aldeia de Refúgio Noturno.",
	allegiance = "Círculo Cenariano",
	aliases = { "Rabine" },
	sections = {
		{
			title = "Resumo",
			text = [=[Rabine Saturna é o mordomo do {link:keeper-remulos}Guardião Remulos{/link}. Fala pelo guardião aos que vêm à {link:moonglade}Clareira da Lua{/link} e os recebe em nome de todos os que habitam a clareira sagrada. É paciente e cortês, e nunca esquece uma dívida. O arquivista {link:umber}Umber{/link} o chama de mãe coruja de {link:nighthaven}Refúgio Noturno{/link}, e nem sempre com carinho.]=],
		},
		{
			title = "Importância",
			text = [=[Rabine é a mão que a {link:moonglade}Clareira da Lua{/link} estende ao mundo. Por meio dele, o Círculo pede a estranhos de todos os povos que façam o que seus druidas não conseguem fazer sozinhos. Ele acredita que a preservação de {link:azeroth}Azeroth{/link} é uma causa comum à {link:horde}Horda{/link} e à {link:alliance}Aliança{/link}, sejam quais forem suas disputas, e diga o que disser o Arquidruida de {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Recebe na clareira os enviados do {link:thunder-bluff}Penhasco do Trovão{/link} e de {link:darnassus}Darnassus{/link} e lhes promete proteção ali.
• Envia agentes para o oeste, a {link:silithus}Silithus{/link}, onde outrora se travou uma guerra antiga entre os elfos noturnos e um poder alienígena.
• Envia buscadores às ruínas da {link:southwind-village}Vila do Vento Sul{/link} atrás de um Reliquary of Purity.
• Procura lacrar um fragmento da Felvine de Eldre'Thalas.]=],
		},
	},
	chapters = {
		{
			title = "O Ermo",
			hint = "Leve a carta do mordomo aos ermos além de Un'Goro.",
			text = [=[A oeste da {link:un-goro-crater}Cratera Un'Goro{/link} fica um deserto de que poucos elfos noturnos se lembram. Há muito tempo, seu povo combateu ali um inimigo terrível e o selou. Rabine teme que algo agora trabalhe para despertá-lo. Mandou uma carta a {link:layo-starstrike}Layo Starstrike{/link}, o agente do Círculo no {link:valor-s-rest}Repouso dos Valorosos{/link}, o cemitério dos caídos dos ermos. O que Layo encontrou ali começou a lhe dar razão. Com o tempo, Layo mandou para casa um objeto estranho lacrado em quitina, destinado ao arquivista de {link:nighthaven}Refúgio Noturno{/link}.]=],
		},
		{
			title = "A Felvine",
			hint = [=[Traga ao mordomo um fragmento da vinha corrompida, bem lacrado.]=],
			text = [=[Nos salões orientais de Eldre'Thalas, em {link:feralas}Feralas{/link}, um {link:satyrs}sátiro{/link} chamado Alzzin the Wildshaper tomara o Fruit of Fertility e o corrompera, transformando-o na Felvine. Nenhum recipiente comum podia conter coisa tão vil. Rabine lembrou-se de um Reliquary of Purity deixado na {link:southwind-village}Vila do Vento Sul{/link}, em {link:silithus}Silithus{/link}, muitos anos antes. Quando o relicário foi recuperado e o fragmento lacrado dentro dele, ele declarou o portador um herói do Círculo. A guerra, avisou, estava longe de terminar.]=],
		},
	},
	mentions = {
		{ text = "Rabine Saturna" },
		{ text = "Rabine Saturna" },
		{ text = "Wasteland" },
		{ text = "Uncovering Past Secrets" },
		{ text = "A Reliquary of Purity" },
		{ text = "Shards of the Felvine" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Guardião Remulos", note = "seu mestre" },
		{ id = "umber", name = "Umber", note = "o arquivista do Círculo" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "envia-lhe os taurens" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "envia-lhe os elfos noturnos" },
	},
})

Translate("ptBR", "dendrite-starblaze", {
	title = "Dendrite Starblaze",
	subtitle = "Mestre dos Jovens Druidas",
	found = "Refúgio Noturno, no norte da aldeia",
	hint = [=[Procure o druida de Refúgio Noturno que ensina aos jovens suas primeiras formas.]=],
	allegiance = "Círculo Cenariano",
	aliases = { "Dendrite" },
	sections = {
		{
			title = "Resumo",
			text = [=[Dendrite Starblaze é um druida do {link:cenarion-circle}Círculo Cenariano{/link} que ensina em {link:nighthaven}Refúgio Noturno{/link}. Quase todo jovem druida dos elfos noturnos e dos taurens passa por suas mãos. Ele recebe cada um com uma prece silenciosa ao Pai {link:cenarius}Cenarius{/link} e um pequeno gesto invisível que o enche de poder. Depois os envia para aprender com a própria natureza selvagem.]=],
		},
		{
			title = "Importância",
			text = [=[Dendrite mantém a tradição mais antiga dos druidas: as formas da natureza precisam ser conquistadas, não simplesmente concedidas. Ele envia seus alunos aos grandes espíritos, ao lago e às feras doentes do mundo, e os julga pelo que trazem de volta. Agora druidas {link:skyborne}shen'dorei{/link} também vêm a ele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia jovens druidas ao {link:great-bear-spirit}Grande Espírito do Urso{/link} para aprender a natureza do urso.
• Impõe a Prova do Lago e a Prova do Leão-marinho aos que desejam assumir a forma aquática.
• Enviou jovens druidas à {link:darkshore}Costa Negra{/link} quando {link:auberdine}Auberdine{/link} pediu ajuda à {link:moonglade}Clareira da Lua{/link} com cervos envenenados.
• Envia alunos ao {link:great-cat-spirit}Grande Espírito do Gato{/link}, e os {link:skyborne}shen'dorei{/link} a um espírito de sua própria terra natal.]=],
		},
	},
	chapters = {
		{
			title = "O Caminho da Garra",
			hint = "Procure o Grande Espírito do Urso a pedido de Dendrite.",
			text = [=[A primeira lição de Dendrite é sempre o urso. Ele envia cada aluno ao {link:great-bear-spirit}Grande Espírito do Urso{/link}, no noroeste da clareira, e espera. Quando voltam, procura uma mudança em seus olhos: uma nova sabedoria, força ainda sem foco.]=],
		},
		{
			title = "Veneno na Água",
			hint = "Ajude os cervos da Costa Negra em nome do Círculo.",
			text = [=[{link:auberdine}Auberdine{/link} pedira ajuda à {link:moonglade}Clareira da Lua{/link}, e Dendrite fez disso uma lição. Não era um exercício, avisou. A água das {link:cliffspring-falls}Quedas de Fontescarpa{/link} estava envenenando os cervos da {link:darkshore}Costa Negra{/link}, e o aluno tinha de curá-los com as mãos, como faria um leigo, antes de aprender a fazê-lo com uma palavra. Auberdine mandou seus agradecimentos. Dendrite acrescentou um aviso próprio: alguns em {link:darnassus}Darnassus{/link} escolhem não ver a corrupção que se espalha pela terra.]=],
		},
		{
			title = "O Grande Gato",
			hint = "Conquiste a bênção do Grande Espírito do Gato.",
			text = [=[Nestes dias, Dendrite também envia seus alunos para o sul, ao {link:great-cat-spirit}Grande Espírito do Gato{/link}, junto aos {link:stormrage-barrow-dens}Templos de Tempesfúria{/link}. Para os {link:skyborne}shen'dorei{/link} ele tem outro guia: um espírito felino alado de sua própria ilha, que veio à clareira e pediu por eles pelo nome.]=],
		},
	},
	mentions = {
		{ text = "Moonglade" },
		{ text = "Moonglade" },
		{ text = "Great Bear Spirit" },
		{ text = "A Lesson to Learn" },
		{ text = "Trial of the Sea Lion" },
		{ text = "Lessons Anew" },
		{ text = "Power over Poison" },
		{ text = "The Great Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-bear-spirit", name = "Grande Espírito do Urso", note = "o primeiro mestre de seus alunos" },
		{ id = "great-cat-spirit", name = "Grande Espírito do Gato", note = "põe seus alunos à prova" },
		{ id = "avatar-of-saeyleenan", name = "Avatar de Saeyleenan", note = "ensina seus alunos shen'dorei" },
		{ id = "tajarri", name = "Tajarri", note = "julga a Prova do Lago" },
		{ id = "alanndarian-nightsong", name = "Alanndarian Nightsong", note = "pediu ajuda à Clareira da Lua" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "envia-lhe alunos" },
	},
})

Translate("ptBR", "umber", {
	title = "Umber",
	subtitle = "Arquivista do Círculo Cenariano",
	found = "Entre as estantes de Refúgio Noturno",
	hint = [=[Procure o arquivista que vagueia pelas estantes de Refúgio Noturno.]=],
	allegiance = "Círculo Cenariano",
	sections = {
		{
			title = "Resumo",
			text = [=[Umber é o arquivista do {link:cenarion-circle}Círculo Cenariano{/link}. É brilhante, esquecido e um pouco excêntrico, e já salvou tomos em estado pior do que a maioria dos estudiosos ousaria abrir. Resmunga consigo mesmo enquanto procura nas estantes papéis que perdeu. Ouviu os comentários sussurrados sobre horrores no deserto. Não tem amor a insetos de espécie alguma e fica contente em ficar com seus livros.]=],
		},
		{
			title = "Importância",
			text = [=[Umber abriu a primeira janela para o passado de {link:silithus}Silithus{/link}. Um pedaço de quitina enviado do deserto revelou conter um diário, escrito numa forma muito antiga da língua dos elfos noturnos.]=],
		},
	},
	mentions = {
		{ text = "Umber, Archivist" },
		{ text = "Uncovering Past Secrets" },
		{ text = "Under the Chitin Was..." },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "a mãe coruja, em suas palavras" },
	},
})

Translate("ptBR", "loganaar", {
	title = "Loganaar",
	subtitle = "Instrutor de Druidas de Refúgio Noturno",
	found = "Refúgio Noturno",
	hint = [=[Procure o druida que treina os membros do próprio Círculo em Refúgio Noturno.]=],
	allegiance = "Círculo Cenariano",
	sections = {
		{
			title = "Resumo",
			text = [=[Loganaar ensina as artes do druida em {link:nighthaven}Refúgio Noturno{/link}. Ao contrário dos mestres de {link:darnassus}Darnassus{/link} e do {link:thunder-bluff}Penhasco do Trovão{/link}, não serve a nenhuma cidade. Treina qualquer druida do Círculo que venha à clareira, {link:night-elves}elfo noturno{/link} ou {link:tauren}tauren{/link}, e nada pede de suas cidades nem de suas disputas. Num Círculo dividido entre a {link:moonglade}Clareira da Lua{/link} e Darnassus, suas lições pertencem apenas à clareira.]=],
		},
		{
			title = "Importância",
			text = [=[Loganaar é muitas vezes quem ouve quando alguém distante pede a ajuda de um druida. Quando um caçador chamado {link:torwa-pathfinder}Torwa Pathfinder{/link} mandou dizer da {link:un-goro-crater}Cratera Un'Goro{/link} que só um druida poderia ajudá-lo, foi Loganaar quem passou a mensagem adiante.]=],
		},
	},
	mentions = {
		{ text = "{link:torwa-pathfinder}Torwa Pathfinder{/link}" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "ensina na mesma aldeia" },
	},
})

Translate("ptBR", "tajarri", {
	title = "Tajarri",
	subtitle = "Guardiã do Santuário de Remulos",
	found = "O Santuário de Remulos",
	hint = "Fale com a guardiã que cuida do santuário do guardião.",
	allegiance = "Círculo Cenariano · Guardiões da Clareira da Lua",
	sections = {
		{
			title = "Resumo",
			text = [=[Tajarri é uma das guardiãs de maior confiança da {link:moonglade}Clareira da Lua{/link}. Ela cuida do {link:shrine-of-remulos}Santuário de Remulos{/link} e considera isso um privilégio. Vigia os jovens druidas que correm do lago com bugigangas que se desfazem nas mãos, e os apressa quando o tempo fica curto. Outros druidas podem estar vasculhando as mesmas águas, e a bugiganga não espera. Ela conhece também a segunda prova, e manda os que procuram as metades do Pendant of the Sea Lion perguntar ao povo da clareira onde elas estão.]=],
		},
		{
			title = "Importância",
			text = [=[Tajarri é a juíza da Prova do Lago. Por meio dela, cada jovem druida aprende que o santuário honra o dever mais antigo do Círculo, a manutenção do equilíbrio da natureza.]=],
		},
	},
	mentions = {
		{ text = "Trial of the Lake" },
		{ text = "Trial of the Lake" },
		{ text = "Trial of the Sea Lion" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Guardião Remulos", note = "o senhor de seu santuário" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "envia-lhe os jovens" },
	},
})

Translate("ptBR", "great-bear-spirit", {
