	mentions = {
		{ text = "Great Bear Spirit" },
		{ text = "Great Bear Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "envia-lhe alunos" },
		{ id = "urs-endris", name = "Urs'endris", note = "o espírito do urso de Zephras" },
	},
})

Translate("ptBR", "great-cat-spirit", {
	title = "Grande Espírito do Gato",
	subtitle = "Mestre da Sombra Silenciosa",
	found = "O sul da Clareira da Lua, a oeste dos Templos de Tempesfúria",
	hint = [=[Procure o espírito do gato perto dos túmulos no sul da clareira.]=],
	allegiance = "Os espíritos da natureza selvagem · Círculo Cenariano",
	sections = {
		{
			title = "Resumo",
			text = [=[O Grande Espírito do Gato habita o sul da {link:moonglade}Clareira da Lua{/link}, perto dos {link:stormrage-barrow-dens}Templos de Tempesfúria{/link}. Ensina aos jovens druidas a natureza do gato: astúcia, furtividade e ferocidade quando não resta caminho para fugir. Só palavras não o satisfazem. Os que vêm a ele devem mostrar o que são, não dizê-lo.]=],
		},
		{
			title = "Importância",
			text = [=[Os que desejam assumir sua forma precisam primeiro recuperar três relíquias de seu favor nos templos, passando pelos espíritos enfurecidos dos Druidas da Garra. Uma estátua na entrada dos templos lhes empresta furtividade. Só quando as três relíquias são devolvidas ele dá sua bênção, e deseja a seus alunos sombras que os escondam e presas que caiam facilmente em suas garras.]=],
		},
	},
	mentions = {
		{ text = "The Great Cat Spirit" },
		{ text = "Blessings of the Great Cat Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "envia-lhe alunos" },
		{ id = "avatar-of-saeyleenan", name = "Avatar de Saeyleenan", note = "um espírito felino de Zephras" },
	},
})

Translate("ptBR", "avatar-of-saeyleenan", {
	title = "Avatar de Saeyleenan",
	subtitle = "O Grande Espírito Felino Alado",
	found = "O sul da Clareira da Lua, ao sul das pontes gêmeas",
	hint = [=[Procure o espírito alado que veio de uma ilha distante para o sul da clareira.]=],
	allegiance = "Os espíritos de Zephras",
	aliases = { "Saeyleenan" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Avatar de Saeyleenan é um espírito felino alado da {link:zephras-isle}Ilha de Zephras{/link}, a terra natal dos {link:skyborne}shen'dorei{/link}. Apareceu recentemente na {link:moonglade}Clareira da Lua{/link} e pediu aos druidas de {link:nighthaven}Refúgio Noturno{/link} que lhe enviassem os jovens druidas de seu povo. Ensina-lhes a forma felina de Zephras, que difere um pouco da forma conhecida em {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[O Avatar é um sinal de que os espíritos de {link:zephras-isle}Zephras{/link} não esqueceram seus filhos. Impõe-lhes a mesma prova do {link:great-cat-spirit}Grande Espírito do Gato{/link}, nos túmulos a leste de seu lugar. Aos que passam, dá sua bênção e o desejo de que os ventos guiem seus passos. Tem pouco mais a lhes ensinar aqui, diz ele, e espera revê-los em Zephras.]=],
		},
	},
	mentions = {
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "Blessings of the Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-cat-spirit", name = "Grande Espírito do Gato", note = "seu equivalente na clareira" },
		{ id = "urs-endris", name = "Urs'endris", note = "um grande espírito da mesma ilha" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "guia seus alunos" },
	},
})
